import{_ as o,o as t,c as i,ai as a}from"./chunks/framework.DQi1ytmF.js";const u=JSON.parse('{"title":"Service scopes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/app/service-scopes.md","filePath":"guide/app/service-scopes.md"}'),r={name:"guide/app/service-scopes.md"};function s(c,e,l,n,d,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/guide/app/service-scopes.md for this page in Markdown format</div><h1 id="service-scopes" tabindex="-1">Service scopes <a class="header-anchor" href="#service-scopes" aria-label="Permalink to &quot;Service scopes&quot;">​</a></h1><p><code>scope</code> decides how many instances of a <code>craftService</code> exist and who has to provide it. It is the one decision to make when declaring a service.</p><div class="tip custom-block"><p class="custom-block-title">Short version</p><p>Default to <code>function</code>. Move to <code>toProvide</code> the day a child component needs the same instance. Use <code>global</code> only for genuinely app-wide state.</p></div><h2 id="supported-scopes" tabindex="-1">Supported Scopes <a class="header-anchor" href="#supported-scopes" aria-label="Permalink to &quot;Supported Scopes&quot;">​</a></h2><h3 id="global" tabindex="-1"><code>global</code> <a class="header-anchor" href="#global" aria-label="Permalink to &quot;`global`&quot;">​</a></h3><ul><li>singleton provided at root</li><li>ideal for app-wide services and shared state</li><li>no explicit <code>provideX()</code> helper</li></ul><h3 id="toprovide" tabindex="-1"><code>toProvide</code> <a class="header-anchor" href="#toprovide" aria-label="Permalink to &quot;`toProvide`&quot;">​</a></h3><ul><li>requires <code>provideX()</code> where the service is mounted</li><li>useful for feature-local service trees</li><li>works well with tests that need explicit providers</li></ul><h3 id="manuallyprovidedatroot" tabindex="-1"><code>manuallyProvidedAtRoot</code> <a class="header-anchor" href="#manuallyprovidedatroot" aria-label="Permalink to &quot;`manuallyProvidedAtRoot`&quot;">​</a></h3><ul><li>explicit provider helper, but designed to be mounted at root</li><li>also exposes <code>XToProvide</code> for public provider composition</li><li>allows this scope to be yielded by global services, which is not possible with <code>toProvide</code> (it still requires explicit setup when testing with <code>setupCraftServiceTestingByRegister</code>).</li></ul><h3 id="function" tabindex="-1"><code>function</code> <a class="header-anchor" href="#function" aria-label="Permalink to &quot;`function`&quot;">​</a></h3><ul><li>creates a fresh instance on each injection</li><li>useful for reusable factories with bindings and inputs</li></ul><h3 id="abstract" tabindex="-1"><code>abstract</code> <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;`abstract`&quot;">​</a></h3><ul><li>declares a contract without implementation</li><li>exposes a requirement token to force a concrete implementation later</li></ul><h2 id="recommendations-for-choosing-a-scope" tabindex="-1">Recommendations For Choosing a Scope <a class="header-anchor" href="#recommendations-for-choosing-a-scope" aria-label="Permalink to &quot;Recommendations For Choosing a Scope&quot;">​</a></h2><ul><li>Prefer <code>function</code> for a service owned by a single component. It avoids an explicit provider and makes it clear the instance is not meant to be shared with other components or child components.</li><li>Move to <code>toProvide</code> when the same instance must be shared with child components, or across several components through a common parent or route. In that case, provide it at the component boundary, a parent component, or the route.</li><li>Be careful with <code>toProvide</code>: Angular does not report a compilation error when the provider is missing, so the failure usually appears at runtime instead. The <a href="/craft/guide/routing/setup.html">route DI check</a> closes that hole; <a href="/craft/guide/testing/architecture.html#assertroutediproofs">architecture tests</a> keep the check armed.</li><li>Use <code>global</code> when the instance is intentionally shared application-wide.</li><li>For startup-only logic that should run when the app boots but is not injected elsewhere, prefer <code>function</code> together with <code>provideAppInitializer(...)</code>. If the same instance also needs to be injected by other services, use <code>global</code> instead.</li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="/craft/guide/app/craft-service.html">craftService</a></li><li><a href="/craft/guide/routing/route-providers.html">Route providers</a> — providing a service from a route</li><li><a href="/craft/guide/testing/services.html">Testing services</a></li></ul>',19)])])}const m=o(r,[["render",s]]);export{u as __pageData,m as default};
